    public ProcedureOrderService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ProcedureOrderEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ProcedureOrderRepository.class) );
		this.validator		= applicationContext.getBean(ProcedureOrderValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		ProcedureOrder
	 */
		public ProcedureOrder createProcedureOrder( CreateProcedureOrderCommand command ) {

		ProcedureOrder entity = new ProcedureOrder();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setProcedureOrderId( command.getProcedureOrderId() );
            entity.setProcedureCode( command.getProcedureCode() );
            entity.setConsentObtained( command.getConsentObtained() );
            entity.setAnesthesiaType( command.getAnesthesiaType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of ProcedureOrder {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateProcedureOrderCommand
	 * @return		ProcedureOrder
	 */
	public ProcedureOrder updateProcedureOrder( UpdateProcedureOrderCommand command ) {

		ProcedureOrder entity = new ProcedureOrder();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setProcedureOrderId( command.getProcedureOrderId() );
            entity.setProcedureCode( command.getProcedureCode() );
            entity.setConsentObtained( command.getConsentObtained() );
            entity.setOrder( command.getOrder() );
            entity.setFacility( command.getFacility() );
            entity.setProcedure( command.getProcedure() );
            entity.setAnesthesiaType( command.getAnesthesiaType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of ProcedureOrder {0} ", entity.toString() );

		return entity;
	}

